INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(24, 'Áo Polo Modal Slim Fit', '100% Cotton', 5, '1000000', '750000', '<ul><li><p style=\"margin-left:0px;\">Áo polo cổ đức</p></li><li><p style=\"margin-left:0px;\">Thiết kế tay ngắn</p></li><li><p style=\"margin-left:0px;\">Cài khuy&nbsp;thời thượng</p></li><li><p style=\"margin-left:0px;\">Tạo điểm nhấn mix màu viền</p></li><li><p style=\"margin-left:0px;\">Trước ngực có thêu logo</p></li><li><p style=\"margin-left:0px;\">Kiểu dáng&nbsp;Slim fit</p></li><li><p style=\"margin-left:0px;\">Chất liệu&nbsp;58% Cotton, 39% Modal, 3% Spandex</p></li><li><p style=\"margin-left:0px;\">Thoáng khí, thấm hút mồ hôi</p></li><li><p style=\"margin-left:0px;\">Mềm mại, thoải mái</p></li><li><p style=\"margin-left:0px;\">An toàn cho da</p></li><li><p style=\"margin-left:0px;\">Dễ dàng mix&amp;match với nhiều kiểu trang phục khác nhau</p></li></ul>', '<ul><li><figure class=\"table\" style=\"width:300px;\"><table style=\"background-color:rgb(255, 255, 255);border-width:0px;\"><tbody><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Dòng sản phẩm</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Men</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Nhóm sản phẩm</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Áo</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Cổ áo</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Cổ đức</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Tay áo</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Tay cộc</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Kiểu dáng</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Slim fit</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Độ dài</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Dài thường</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Họa tiết</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Trơn</td></tr><tr><td style=\"border-width:0px;padding:0px 0px 5px;\"><strong>Chất liệu</strong></td><td style=\"border-width:0px;padding:0px 0px 5px;\">Thun</td></tr></tbody></table></figure></li><li><p style=\"margin-left:0px;\"><strong>Thông tin mẫu:</strong></p></li><li><p style=\"margin-left:0px;\"><strong>Chiều cao: </strong>180 cm</p></li><li><p style=\"margin-left:0px;\"><strong>Cân nặng: </strong>70 kg</p></li><li><p style=\"margin-left:0px;\"><strong>Số đo 3 vòng: </strong>92-78-98 cm</p></li><li><p style=\"margin-left:0px;\">Mẫu mặc size: L</p></li><li><p style=\"margin-left:0px;\">Lưu ý: Màu sắc sản phẩm thực tế sẽ có sự chênh lệch nhỏ so với ảnh do điều kiện ánh sáng khi chụp và màu sắc hiển thị qua màn hình máy tính/ điện thoại.</p></li><li><figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure></li></ul>', '/storage/images/1732875128-5b043f1cb6e717a95fbf2b1dfe6e4ffa.jpg', '/storage/images/1732875135-187a6a40cc13bfd244efd6b5bb3e3a7d.jpg*/storage/images/1732875135-a4ac8ba10265ed2746d77fd9397169cd.jpg*/storage/images/1732875135-d2488401006d3911676c65a44921601e.jpg', '2024-11-29 03:14:21', '2024-11-29 06:50:37');
