(28, 'Áo Polo Slim fit Point Man', '100% Cotton', 5, '1200000', '999000', '<ul><li><p style=\"margin-left:0px;\">Áo polo cổ đức</p></li><li><p style=\"margin-left:0px;\">Thiết kế tay ngắn</p></li><li><p style=\"margin-left:0px;\">Cổ đức cài khuy&nbsp;thời thượng</p></li><li><p style=\"margin-left:0px;\">Trước ngực có thêu logo</p></li><li><p style=\"margin-left:0px;\">Kiểu dáng&nbsp;Slim fit</p></li><li><p style=\"margin-left:0px;\">Chất liệu&nbsp;58% Cotton, 39% Modal, 3% Spandex</p></li><li><p style=\"margin-left:0px;\">Thoáng khí, thấm hút mồ hôi</p></li><li><p style=\"margin-left:0px;\">Mềm mại, thoải mái</p></li><li><p style=\"margin-left:0px;\">Dễ dàng mix&amp;match với nhiều kiểu trang phục khác nhau</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>', '/storage/images/1732876142-596cd8faa1665e3f4eaf8cf171ce37f9.jpg', '/storage/images/1732876149-6cd0e10dc35821e77b41a26f64221af1.jpg*/storage/images/1732876149-9111cc11f54373efbeebe4b683865d68.jpg*/storage/images/1732876149-c05eec864961d3e1c48633906ec6318d.jpg', '2024-11-29 03:30:03', '2024-11-29 06:51:42');
INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(29, 'Áo khoác Khaki Cropped Jacket', 'Khaki', 3, '1000000', '999000', '<ul><li><p style=\"margin-left:0px;\">Áo khoác cổ đức</p></li><li><p style=\"margin-left:0px;\">Thiết kế tay dài</p></li><li><p style=\"margin-left:0px;\">Khuy cài thân trước và gấu tay</p></li><li><p style=\"margin-left:0px;\">Có 2 túi tiện lợi, thời trang</p></li><li><p style=\"margin-left:0px;\">Độ dài thường</p></li><li><p style=\"margin-left:0px;\">Kiểu dáng suông</p></li><li><p style=\"margin-left:0px;\">Chất liệu Khaki</p></li><li><p style=\"margin-left:0px;\">Áo đứng form, bền bỉ</p></li><li><p style=\"margin-left:0px;\">Đặc tính nhẹ, thoáng khí</p></li><li><p style=\"margin-left:0px;\">Thích hợp cho nhiều phong cách khác nhau</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure>', '/storage/images/1732876330-b2b335e0c242dd317dffaf521ab81455.jpg', '/storage/images/1732876336-84c28e0f6aaf4e44ac0623cc90074091.jpg*/storage/images/1732876336-39905aa7418003634131dd7fbbb9447c.jpg*/storage/images/1732876336-c841706f33271b31d51dc2447f3d2371.jpg', '2024-11-29 03:32:57', '2024-11-29 06:52:29');
INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(30, 'Áo khoác Thu Đông', 'Lông Cừu', 3, '5000000', '3000000', '<ul><li><p style=\"margin-left:0px;\">Áo khoác Bomber&nbsp;không chỉ là một sản phẩm mặc giữ ấm mà còn là biểu tượng cho phong cách thời trang hiện đại và sự lịch lãm của Quý anh. Thiết kế chất lượng cao, chú trọng đến chi tiết, lựa chọn đáng giá trong tủ đồ mùa Đông này:&nbsp;</p></li><li><p style=\"margin-left:0px;\">Áo bomber trẻ trung, nam tính. Form áo&nbsp;rộng rãi, mang đến cảm giác thoải mái ngay cả khi vận động ngoài trời.&nbsp;</p></li><li><p style=\"margin-left:0px;\">Thiết kế basic với gam màu đen.&nbsp;</p></li><li><p style=\"margin-left:0px;\">Sản phẩm áo khoác không bai, không xù, không phai màu kể cả khi giặt máy. Khả năng chống bám bụi và giữ ấm hiệu quả nhờ tuân thủ nghiêm ngặt quy trình sản xuất đạt tiêu chuẩn Mỹ.&nbsp;</p></li><li><p style=\"margin-left:0px;\">Thiết kế dễ dàng kết hợp với nhiều trang phục khác nhau như jean, quần kaki, hoặc thậm chí có thể mặc thay suit để tạo phong cách ấm áp và lịch lãm.</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure>', '/storage/images/1732876599-ec293a2d9f7fb268999711ad17d18f00.jpg', '/storage/images/1732876606-8a54c0b65816ac34727fedfa4ef38e1a.jpg*/storage/images/1732876606-33eef2b148cddac7aaef3e330b3e68eb.jpg*/storage/images/1732876606-5956429f22ed3e77ee4942cd82e559d5.jpg', '2024-11-29 03:36:49', '2024-11-29 06:52:55');
INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(31, 'Áo sơ mi Regular Linen Cotton', '100% Cotton', 2, '1200000', '1000000', '<ul><li><p style=\"margin-left:0px;\">Áo sơ mi cổ tàu</p></li><li><p style=\"margin-left:0px;\">Khuy cài phần cổ</p></li><li><p style=\"margin-left:0px;\">Thiết kế túi ngực, thêu logo</p></li><li><p style=\"margin-left:0px;\">Kiểu dáng&nbsp;Regular&nbsp;</p></li><li><p style=\"margin-left:0px;\">Họa tiết trơn</p></li><li><p style=\"margin-left:0px;\">Chất liệu&nbsp;Linen Cotton&nbsp;</p></li><li><p style=\"margin-left:0px;\">Mềm mại, thoải mái</p></li><li><p style=\"margin-left:0px;\">Thấm hút&nbsp;mồ hôi tốt</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure>', '/storage/images/1732876721-6cbfd50b5b118da70bdf5ec60247f4a0.jpg', '/storage/images/1732876731-5a89a3bea07e84f5a30a06cc53f4a9db.jpg*/storage/images/1732876731-b2f0ac4be7176c38810272acc1279df2.jpg*/storage/images/1732876731-bef0354928bd055bd86364585bdd56eb.jpg', '2024-11-29 03:39:51', '2024-11-29 06:53:11');
INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(32, 'Sơ mi trơn lịch lãm', '100% Cotton', 2, '599000', '399000', '<ul><li><p style=\"margin-left:0px;\">Áo sơ mi Slim fit, cổ đức. Tay áo dài, độ dài thường, màu sắc trơn. Thiết kế áo khuy cài phía trước và&nbsp; khuy cố định ở cổ, tay áo. Áo lựa chọn chất liệu vải&nbsp;mềm mịn, được dệt đan sợi dưới nền vải.</p></li><li><p style=\"margin-left:0px;\">Kiểu dáng&nbsp;Slim fit thiết kế form ôm nhẹ, tôn đường nét của cơ thể.&nbsp;Tông màu lịch lãm, dễ phối nhiều trang phục như quần jean, short, quần tây...&nbsp;Áo có thể sơ vin hoặc thả suông.&nbsp;</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure>', '/storage/images/1732876984-e5974032708e9b41ee38e20872b19406.jpg', '/storage/images/1732876990-91138f674c51af326cbee5fb94f2fdfb.jpg*/storage/images/1732876990-478036720e9efaa9c554864bb43f87ff.jpg*/storage/images/1732876990-c0019197964c6cd1575f78d68ce0cfe7.jpg', '2024-11-29 03:43:39', '2024-11-29 06:53:25');
INSERT INTO `products` (`id`, `name`, `material`, `category_id`, `price_normal`, `price_sale`, `description`, `content`, `image`, `image_list`, `created_at`, `updated_at`) VALUES
(33, 'Áo sơ mi vải thô phối túi', '100% Cotton', 2, '600000', '300000', '<ul><li><p style=\"margin-left:0px;\">Áo sơ mi tay dài cổ đức lịch thiệp.</p></li><li><p style=\"margin-left:0px;\">Thiết kế kiểu&nbsp;dáng Slim fit ôm nhẹ, phù hợp vóc dáng Á - Đông.</p></li><li><p style=\"margin-left:0px;\">Họa tiết trơn, basic, trẻ trung và hiện đại.&nbsp;</p></li><li><p style=\"margin-left:0px;\">Kết hợp&nbsp;cùng quần âu, quần jeans, kaki phù hợp diện đi làm, đi chơi, gặp gỡ đối tác.</p></li></ul>', '<figure class=\"image\"><img style=\"aspect-ratio:1770/720;\" src=\"data:image/jpeg;base64,\" width=\"1770\" height=\"720\"></figure>', '/storage/images/1732877313-1c58e280e000fbfd36c0d738edc0e26b.jpg', '/storage/images/1732877318-4f3c2e0a4cbbfee882667243d167ef28.jpg*/storage/images/1732877318-721b2b358e13e97fb34231eb83272923.jpg*/storage/images/1732877318-a4994fea90407466b2f59fead1b09c61.jpg', '2024-11-29 03:49:28', '2024-11-29 06:53:40');
